// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        // Bank helper acts as the token contract; airDrop requires caller be Bank-like.
        Bank bank = new Bank();
        vm.assume(actor != address(bank));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        // drive airDrop from the Bank-like counterparty
        vm.prank(address(bank));
        try c.airDrop() {
            // succeeded
        } catch {
            // reverted; harmless
        }

        // General rule: whenever an airDrop attempt completes, the lock is
        // released again (or was never taken on revert) -> _locked() is false.
        assertTrue(!c._locked());
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
